class Solution {
    public int minPatches(int[] nums, int n) {
        long coverage = 0;
        int index = 0;
        int patches = 0;
        while (coverage < n) {
            while (index < nums.length && nums[index] <= coverage + 1) {
                coverage += nums[index];
                index++;
                if (coverage >= n) return patches;
            }
            coverage += coverage + 1;
            patches++;
        }
        return patches;
    }
}

class Solution {
    public int minPatches(int[] nums, int n) {
        long coverage = 0;
        int index = 0;
        int patches = 0;
        while (coverage < n) {
            long nextValue = index < nums.length ? nums[index] : Long.MAX_VALUE;
            if (nextValue <= coverage + 1) {
                coverage += nextValue;
                index++;
                continue;
            }
            long limit = Math.min((long) n, nextValue - 1);
            while (coverage < limit) {
                long patch = coverage + 1;
                coverage += patch;
                patches++;
            }
        }
        return patches;
    }
}

class Solution {
    public int minPatches(int[] nums, int n) {
        return solve(nums, n, 0, 1L);
    }

    private int solve(int[] nums, int n, int index, long miss) {
        if (miss > n) return 0;
        if (index < nums.length && nums[index] <= miss) {
            return solve(nums, n, index + 1, miss + nums[index]);
        }
        return 1 + solve(nums, n, index, miss + miss);
    }
}
